const input = $input.first()?.json ?? {};
for (const field of ['run_id', 'history_id', 'step_key', 'step_title', 'project_question']) {
  if (typeof input[field] !== 'string' || !input[field].trim()) throw new Error('missing required field: ' + field);
}
if (!/^[0-9a-f-]{36}$/i.test(input.run_id)) throw new Error('run_id must be a UUID');
const stepOrder = Number(input.step_order);
if (!Number.isInteger(stepOrder) || stepOrder < 1 || stepOrder > 7) throw new Error('step_order must be between 1 and 7');
const decisionState = input.decision_state && typeof input.decision_state === 'object' ? input.decision_state : { steps: {} };
return [{ json: { ...input, step_order: stepOrder, decision_state: { ...decisionState, steps: decisionState.steps && typeof decisionState.steps === 'object' ? decisionState.steps : {} } } }];

const state = $input.first().json;
const output = state.decision_state.steps[state.step_key];
return [{ json: { run_id: state.run_id, step_key: state.step_key, step_order: state.step_order, status: 'completed', output, decision_state: state.decision_state } }];

