INSERT INTO analysis_step_outputs (run_id, step, step_order, status, input_snapshot, quality_gate, updated_at)
VALUES ($1::uuid, $2::text, $3::integer, 'running', $4::jsonb, '{}'::jsonb, NOW())
ON CONFLICT (run_id, step) DO UPDATE SET step_order = EXCLUDED.step_order, status = 'running', input_snapshot = EXCLUDED.input_snapshot, updated_at = NOW();
UPDATE analysis_runs SET status = 'running', current_step = $2::text, started_at = COALESCE(started_at, NOW()), heartbeat_at = NOW(), lease_expires_at = NOW() + INTERVAL '6 hours', updated_at = NOW() WHERE id = $1::uuid;
SELECT $1::text AS run_id;

