const state = $('Validate Step Request').first().json;
const memo = $input.first()?.json ?? {};
if (memo.error || memo.detail) throw new Error('codex_harness_failed:' + String(memo.error?.message ?? memo.detail ?? memo.error));
const actions = Array.isArray(memo.actions) ? memo.actions : [];
if (!String(memo.decision ?? '').trim() || !actions.length) throw new Error('decision_memo_required_content_missing');
const unit = state.decision_unit;
const output = { unit_id: String(unit.unit_id), step_key: state.step_key, step_order: state.step_order, title: String(unit.title), question: String(unit.question), depends_on: Array.isArray(unit.depends_on) ? unit.depends_on : [], decision_output: String(unit.decision_output ?? ''), evidence_focus: String(unit.evidence_focus ?? ''), decision_memo: { decision: String(memo.decision), alternatives_considered: Array.isArray(memo.alternatives_considered) ? memo.alternatives_considered : [], key_facts: Array.isArray(memo.key_facts) ? memo.key_facts : [], named_entities: Array.isArray(memo.named_entities) ? memo.named_entities : [], actions }, citations: [], diagnostics: [] };
const current = state.decision_state && typeof state.decision_state === 'object' ? state.decision_state : {};
const next = { ...current, steps: { ...(current.steps ?? {}), [state.step_key]: output }, research_frame: state.research_frame, decision_units: state.decision_units, current_step: state.step_key };
return [{ json: { result: { run_id: state.run_id, step_key: state.step_key, step_order: state.step_order, status: 'completed', output, decision_state: next } } }];

